import { chromium } from '/tmp/smoke/node_modules/playwright/index.mjs';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 900, height: 700 } });
const errors = [];
page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') errors.push(m.text()); });
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
await page.goto('http://localhost:5179/', { waitUntil: 'networkidle' });
await page.waitForSelector('text=No date selected');
const cells = page.locator('[role="gridcell"], td[role="gridcell"], button[role="gridcell"]');
