// click the 15th day if present
const target = page.getByRole('button', { name: /15/ }).first();
await page.screenshot({ path: '/tmp/smoke/before.png' });
try { await target.click({ timeout: 3000 }); } catch (e) { console.log('click fallback:', e.message.split('\n')[0]); await page.locator('.g-calendar-day, [class*="cell"]').nth(14).click({ timeout: 3000 }).catch(e => console.log('fallback2 fail')); }
await page.waitForTimeout(300);
console.log('text after click:', await page.locator('p, span, div').filter({ hasText: /^Selected:|^No date selected$/ }).allInnerTexts());
await page.screenshot({ path: '/tmp/smoke/after.png' });
console.log('errors:', errors.slice(0, 10));
await browser.close();
EOF
